      { id: 'q2-a', text: 'JavaScript' },
      { id: 'q2-b', text: 'CoffeeScript' },
      { id: 'q2-c', text: 'Go' },
      { id: 'q2-d', text: 'Erlang' },
    ],
    correct: ['q2-a', 'q2-b'],
  },
  {
    id: 'q3',
    number: 3,
    text: 'Which of these languages support first-class functions?',
    options: [
      { id: 'q3-a', text: 'Haskell' },
      { id: 'q3-b', text: 'JavaScript' },
      { id: 'q3-c', text: 'Python' },
