    ],
    correct: ['q3-a', 'q3-b', 'q3-c'],
  },
];

// ── State ─────────────────────────────────────────────────────────────────────

const state = {
  selections: {}, // { qId: Set<optionId> }
  submitted: false,
};

questions.forEach(q => { state.selections[q.id] = new Set(); });

