function CheckboxOption({ qId, option }) {
  const selected = state.selections[qId].has(option.id);

  const wrapper = document.createElement('label');
  wrapper.className = 'checkbox-option' + (selected ? ' is-selected' : '');
  wrapper.htmlFor = option.id;

  const input = document.createElement('input');
  input.type = 'checkbox';
  input.id = option.id;
  input.name = qId;
  input.value = option.id;
  input.checked = selected;
  input.setAttribute('aria-label', option.text);

  input.addEventListener('change', () => {
    const sel = state.selections[qId];
    input.checked ? sel.add(option.id) : sel.delete(option.id);
    render();
  });

  const span = document.createElement('span');
  span.className = 'option-text';
  span.textContent = option.text;

  wrapper.appendChild(input);
  wrapper.appendChild(span);
  return wrapper;
}

function FormField({ question }) {
  const field = document.createElement('div');
  field.className = 'form-field';
  field.setAttribute('role', 'group');
  field.setAttribute('aria-labelledby', `label-${question.id}`);

  // Label row
  const labelRow = document.createElement('div');
  labelRow.className = 'form-field__label';

  const badge = document.createElement('span');
  badge.className = 'form-field__number';
  badge.setAttribute('aria-hidden', 'true');
  badge.textContent = question.number;

  const qText = document.createElement('span');
  qText.className = 'form-field__question';
  qText.id = `label-${question.id}`;
  qText.textContent = question.text;

  labelRow.appendChild(badge);
  labelRow.appendChild(qText);
  field.appendChild(labelRow);

  // Optional help text (first question only)
  if (question.help) {
    const help = document.createElement('p');
    help.className = 'form-field__help';
    help.id = `help-${question.id}`;
    help.textContent = question.help;
    field.setAttribute('aria-describedby', `help-${question.id}`);
    field.appendChild(help);
  }

  // Options list
  const optionsList = document.createElement('div');
  optionsList.className = 'form-field__options';
  optionsList.setAttribute('role', 'list');

  question.options.forEach(opt => {
    const item = document.createElement('div');
    item.setAttribute('role', 'listitem');
    item.appendChild(CheckboxOption({ qId: question.id, option: opt }));
    optionsList.appendChild(item);
  });

  field.appendChild(optionsList);
  return field;
}

function ResultBanner() {
  let correct = 0;
  questions.forEach(q => {
    const sel = state.selections[q.id];
    const correctSet = new Set(q.correct);
    const isCorrect =
      sel.size === correctSet.size &&
      [...sel].every(id => correctSet.has(id));
    if (isCorrect) correct++;
  });

  const banner = document.createElement('div');
  banner.className = 'result-banner';
  banner.setAttribute('role', 'status');
  banner.setAttribute('aria-live', 'polite');

  const h2 = document.createElement('h2');
  h2.textContent = `You scored ${correct} / ${questions.length}`;

  const p = document.createElement('p');
  if (correct === questions.length) {
    p.textContent = 'Perfect score! You really know your programming languages. 🎉';
  } else if (correct >= 2) {
    p.textContent = 'Great work — solid knowledge of programming languages!';
  } else if (correct === 1) {
    p.textContent = 'Not bad! Keep exploring the world of programming languages.';
  } else {
    p.textContent = 'Better luck next time — there\'s always more to learn!';
  }

  banner.appendChild(h2);
  banner.appendChild(p);
  return banner;
}

function QuizForm() {
  const form = document.createElement('form');
  form.className = 'quiz-form';
  form.setAttribute('novalidate', '');
  form.setAttribute('aria-label', 'Computer languages quiz');

  questions.forEach(q => form.appendChild(FormField({ question: q })));

  // Submit
  const actions = document.createElement('div');
  actions.className = 'quiz-actions';

  const btn = document.createElement('button');
  btn.type = 'submit';
  btn.className = 'btn-submit';
  btn.textContent = 'Submit Answers';

  actions.appendChild(btn);
  form.appendChild(actions);

  form.addEventListener('submit', e => {
    e.preventDefault();
    state.submitted = true;
    render();
    document.querySelector('.result-banner')?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  });

  return form;
}

// ── Root render ───────────────────────────────────────────────────────────────

function render() {
  const app = document.getElementById('app');
  app.innerHTML = '';

  // Header
  const header = document.createElement('header');
  header.className = 'quiz-header';
  const h1 = document.createElement('h1');
  h1.textContent = 'Computer Languages Quiz';
  const subtitle = document.createElement('p');
  subtitle.textContent = 'Test your knowledge — select all correct answers for each question.';
  header.appendChild(h1);
  header.appendChild(subtitle);
  app.appendChild(header);

  // Form
  app.appendChild(QuizForm());

  // Result (if submitted)
  if (state.submitted) {
    app.appendChild(ResultBanner());
  }
}

// ── Init ──────────────────────────────────────────────────────────────────────

document.addEventListener('DOMContentLoaded', render);
