+++ b/workspace/sandbox/variants/accessible_minimal/checkbox-group--framework-react--style-dark/claude-sonnet-4.6__s4/styles.css
@@ -1,0 +1,254 @@
+*, *::before, *::after {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+:root {
+  --bg: #0f1117;
+  --surface: #1a1d27;
+  --surface-hover: #22263a;
+  --border: #2e3352;
+  --border-focus: #5c6bc0;
+  --accent: #7c83f5;
+  --accent-dim: rgba(124, 131, 245, 0.15);
+  --accent-check: #a5abff;
+  --text-primary: #e8eaf6;
+  --text-secondary: #8c92b8;
+  --text-help: #6b7299;
+  --success-bg: #0d2137;
+  --success-border: #1e6b4a;
+  --success-text: #4caf8a;
+  --radius: 10px;
+  --radius-sm: 6px;
+  --transition: 150ms ease;
+}
+
+body {
+  background: var(--bg);
+  color: var(--text-primary);
+  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
+  font-size: 16px;
+  line-height: 1.6;
+  min-height: 100vh;
+  display: flex;
+  align-items: flex-start;
+  justify-content: center;
+  padding: 48px 16px 80px;
+}
+
+#app {
+  width: 100%;
+  max-width: 680px;
+}
+
+/* ── Header ── */
+.quiz-header {
+  margin-bottom: 40px;
+}
+
+.quiz-header h1 {
+  font-size: 1.75rem;
+  font-weight: 700;
+  letter-spacing: -0.02em;
+  color: var(--text-primary);
+}
+
+.quiz-header p {
+  margin-top: 6px;
+  color: var(--text-secondary);
+  font-size: 0.95rem;
+}
+
+/* ── Form ── */
+.quiz-form {
+  display: flex;
+  flex-direction: column;
+  gap: 24px;
+}
+
+/* ── form-field ── */
+.form-field {
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  padding: 24px;
+  transition: border-color var(--transition);
+}
+
+.form-field:focus-within {
+  border-color: var(--border-focus);
+}
+
+.form-field__label {
+  display: flex;
+  align-items: baseline;
+  gap: 10px;
+  margin-bottom: 6px;
+}
+
+.form-field__number {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  width: 24px;
+  height: 24px;
+  border-radius: 50%;
+  background: var(--accent-dim);
+  color: var(--accent);
+  font-size: 0.75rem;
+  font-weight: 700;
+  flex-shrink: 0;
+}
+
+.form-field__question {
+  font-size: 1rem;
+  font-weight: 600;
+  color: var(--text-primary);
+  line-height: 1.4;
+}
+
+.form-field__help {
+  font-size: 0.825rem;
+  color: var(--text-help);
+  margin-bottom: 16px;
+  padding-left: 34px;
+}
+
+.form-field__options {
+  display: flex;
+  flex-direction: column;
+  gap: 10px;
+  margin-top: 16px;
+}
+
+/* ── Checkbox option ── */
+.checkbox-option {
+  display: flex;
+  align-items: center;
+  gap: 12px;
+  padding: 12px 14px;
+  border: 1px solid var(--border);
+  border-radius: var(--radius-sm);
+  cursor: pointer;
+  transition: background var(--transition), border-color var(--transition);
+  user-select: none;
+}
+
+.checkbox-option:hover {
+  background: var(--surface-hover);
+  border-color: var(--border-focus);
+}
+
+.checkbox-option input[type="checkbox"] {
+  appearance: none;
+  -webkit-appearance: none;
+  width: 18px;
+  height: 18px;
+  border: 2px solid var(--border);
+  border-radius: 4px;
+  background: transparent;
+  flex-shrink: 0;
+  cursor: pointer;
+  position: relative;
+  transition: background var(--transition), border-color var(--transition);
+}
+
+.checkbox-option input[type="checkbox"]:focus-visible {
+  outline: 2px solid var(--accent);
+  outline-offset: 2px;
+}
+
+.checkbox-option input[type="checkbox"]:checked {
+  background: var(--accent);
+  border-color: var(--accent);
+}
+
+.checkbox-option input[type="checkbox"]:checked::after {
+  content: '';
+  position: absolute;
+  left: 3px;
+  top: 0px;
+  width: 6px;
+  height: 10px;
+  border: 2px solid #0f1117;
+  border-top: none;
+  border-left: none;
+  transform: rotate(45deg);
+}
+
+.checkbox-option.is-selected {
+  background: var(--accent-dim);
+  border-color: var(--accent);
+}
+
+.checkbox-option.is-selected .option-text {
+  color: var(--accent-check);
+}
+
+.option-text {
+  font-size: 0.925rem;
+  color: var(--text-secondary);
+  transition: color var(--transition);
+}
+
+/* ── Submit ── */
+.quiz-actions {
+  margin-top: 8px;
+  display: flex;
+  justify-content: flex-end;
+}
+
+.btn-submit {
+  background: var(--accent);
+  color: #0f1117;
+  border: none;
+  border-radius: var(--radius-sm);
+  padding: 12px 32px;
+  font-size: 0.95rem;
+  font-weight: 700;
+  cursor: pointer;
+  letter-spacing: 0.01em;
+  transition: opacity var(--transition), transform var(--transition);
+}
+
+.btn-submit:hover {
+  opacity: 0.88;
+}
+
+.btn-submit:active {
+  transform: scale(0.97);
+}
+
+.btn-submit:focus-visible {
+  outline: 2px solid var(--accent-check);
+  outline-offset: 3px;
+}
+
+/* ── Result banner ── */
+.result-banner {
+  margin-top: 24px;
+  padding: 20px 24px;
+  border: 1px solid var(--success-border);
+  border-radius: var(--radius);
+  background: var(--success-bg);
+  color: var(--success-text);
+  font-size: 0.95rem;
+  animation: fadeSlideIn 0.3s ease both;
+}
+
+.result-banner h2 {
+  font-size: 1.1rem;
+  margin-bottom: 6px;
+}
+
+.result-banner p {
+  color: #7ecfb0;
+  font-size: 0.875rem;
+}
+
+@keyframes fadeSlideIn {
+  from { opacity: 0; transform: translateY(8px); }
+  to   { opacity: 1; transform: translateY(0); }
+}
+
')
